<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import { getDictionaryItems } from '../../api/modules/settings'; import type { DictionaryItem } from '../../types/settings'
const items=ref<DictionaryItem[]>([]),query=ref(''),category=ref('全部字典'),editing=ref<DictionaryItem|null>(null); const filtered=computed(()=>items.value.filter(i=>(category.value==='全部字典'||i.category===category.value)&&(!query.value||`${i.category}${i.code}${i.name}`.toLowerCase().includes(query.value.toLowerCase()))));onMounted(async()=>items.value=await getDictionaryItems());function create(){editing.value={category:'AMR_STATUS',code:'',name:'',color:'#1677FF',order:50,status:'启用'}}function save(){if(!editing.value)return;const index=items.value.findIndex(i=>i.category===editing.value?.category&&i.code===editing.value?.code);if(index<0)items.value.push({...editing.value});editing.value=null}
</script>
<template><section class="settings-page"><header class="settings-page__header"><div><p class="page-eyebrow">DATA DICTIONARY</p><h1>数据字典</h1></div><button class="settings-primary" @click="create">＋ 新增字典项</button></header><div class="settings-toolbar"><label><span>⌕</span><input v-model="query" placeholder="搜索分类、编码或名称"></label><div><select v-model="category"><option>全部字典</option><option>AMR_STATUS</option><option>TASK_STATUS</option><option>DEVICE_STATUS</option></select></div></div><div class="settings-table-wrap"><table class="settings-table"><thead><tr><th>字典分类</th><th>编码</th><th>显示名称</th><th>颜色</th><th>排序</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in filtered" :key="`${item.category}-${item.code}`"><td class="settings-id">{{item.category}}</td><td class="type-data">{{item.code}}</td><td>{{item.name}}</td><td><span class="dictionary-color"><i :style="{background:item.color}"></i>{{item.color}}</span></td><td>{{item.order}}</td><td><span class="asset-status success">{{item.status}}</span></td><td><button class="table-action" @click="editing={...item}">编辑</button></td></tr></tbody></table></div><div v-if="editing" class="modal-backdrop" @click.self="editing=null"><section class="settings-dialog"><header><div><small>DICTIONARY ITEM</small><strong>{{editing.code?'编辑字典项':'新增字典项'}}</strong></div><button @click="editing=null">×</button></header><div class="settings-dialog__body"><label>字典分类<select v-model="editing.category"><option>AMR_STATUS</option><option>TASK_STATUS</option><option>DEVICE_STATUS</option></select></label><label>编码<input v-model="editing.code"></label><label>显示名称<input v-model="editing.name"></label><label>颜色<input v-model="editing.color" type="color"></label><label>排序<input v-model.number="editing.order" type="number"></label><label>状态<select v-model="editing.status"><option>启用</option><option>停用</option></select></label></div><footer><button @click="editing=null">取消</button><button class="primary" :disabled="!editing.code||!editing.name" @click="save">保存字典项</button></footer></section></div></section></template>
